using System;
using System.Text;

namespace StMarysClassMonitors.Services
{
    public static class EmbeddedAssets
    {
        // Embedded base64 of the complete St. Mary's School standalone web application
        private const string Base64Html = "";

        public static byte[] GetStandaloneHtmlBytes()
        {
            return Convert.FromBase64String(Base64Html);
        }

        public static string GetStandaloneHtmlString()
        {
            return Encoding.UTF8.GetString(GetStandaloneHtmlBytes());
        }
    }
}
